// Title strip: the question, then "{place} · 90 days to {date} · {N} patients counted (...)".
const root = rpt.mount('.rpt-adh-title', { banner: true });
if (!root) { return; }
const w = rpt.rows('A')[0] || {};
const parts = [rpt.place(w.place), w.window_end ? '90 days to ' + rpt.day(w.window_end) : '90 days'];
if (rpt.num(w.cohort_n) !== null) {
  parts.push(rpt.fmt(w.cohort_n) + ' patients counted ' + (rpt.v('include_new') === 'true' ? '(new patients included)' : '(registered before ' + rpt.day(w.window_start) + ')'));
}
root.innerHTML = '<h2 class="rpt-title">Are patients on the medicines the protocol says?</h2>'
  + '<div class="rpt-sub">' + rpt.esc(parts.join(' · ')) + '</div>';

