// Headline strip: BP controlled, On two or more medicines, Off protocol.
const root = rpt.mount('.rpt-adh-head');
if (!root) { return; }
const { esc, fmt, num, yes } = rpt;
const r = rpt.rows('A')[0];
const col = (big, color, label, line, title, few) => '<div' + (title ? ' title="' + esc(title) + '"' : '') + '>'
  + '<div class="rpt-big' + (few ? ' rpt-few' : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + esc(big) + '</div>'
  + '<div class="rpt-label">' + esc(label) + '</div><div class="rpt-line">' + esc(line) + '</div></div>';
const LABELS = ['BP controlled', 'On two or more medicines', 'Off protocol'];
const N = r ? num(r.cohort_n) || 0 : 0;
if (!r || !N) {
  root.innerHTML = '<div class="rpt-strip3">' + LABELS.map((l) => col('—', '', l, rpt.NO_DATA)).join('') + '</div>';
  return;
}
if (yes(r.too_few)) {
  const need = rpt.needAtLeast(r.min_cohort, N);
  root.innerHTML = '<div class="rpt-strip3">' + LABELS.map((l) => col('Too few patients', '', l, need, '', true)).join('') + '</div>';
  return;
}
// Round to one decimal first, so 9.95 reads 10%, not 10.0%.
const p = (k) => rpt.pct(Math.round(1000 * (num(k) || 0) / N) / 10);
root.innerHTML = '<div class="rpt-strip3">'
  + col(p(r.controlled_n), 'var(--controlled)', 'BP controlled', fmt(r.controlled_n) + ' of ' + fmt(N) + ' patients with BP under 140/90 at their latest visit')
  + col(p(r.two_three_n), 'var(--step-4)', 'On two or more medicines', fmt(r.two_three_n) + ' of ' + fmt(N) + ' patients on 2 or 3 medicines')
  + col(p(r.off_n), 'var(--flag-bar)', 'Off protocol', fmt(r.off_n) + ' of ' + fmt(N) + ' patients on another combination or medicines outside the protocol')
  + '</div>';

