// Nine horizontal bars, indigo step ramp; labels from htn_ladder_steps.label (C16).
const frame = (context.panel.data.series || []).find((s) => s.refId === 'A') || (context.panel.data.series || [])[0];
function col(n) { const f = frame && frame.fields.find((x) => x.name === n); if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const C = chartColors;
const rv = context.grafana && context.grafana.replaceVariables;
const allowed = !rv || rv('${isAllowed}') === '1';
// Percent as DESIGN: whole, one decimal under 10%.
const pc = (v) => { const n = Math.round(10 * Number(v)) / 10; return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';
const ord = col('bucket_order').map(Number);
const label = col('label'), cnt = col('patients_n').map((v) => Number(v) || 0), ctl = col('controlled_n').map((v) => Number(v) || 0);
const idx = ord.map((v, i) => i).sort((a, b) => ord[a] - ord[b]);
const N = cnt.reduce((s, v) => s + v, 0);
if (!idx.length || !N) {
  return { graphic: allowed ? [{ type: 'text', left: 'center', top: 'middle', style: { text: 'No data for this place.', fontSize: 14, fill: C.muted } }] : [] };
}
// Steps 1-6 indigo ramp; 7 other protocol combination; 8 outside the protocol; 9 could not read (dashed).
const colorOf = (o) => (o <= 6 ? C.step[o - 1] : o === 7 ? C.stepOther : o === 8 ? C.stepOff : C.estimated);
const end = (i) => fmt(cnt[i]) + ' patients' + (cnt[i] ? ' · ' + pc(100 * ctl[i] / cnt[i]) + ' controlled' : '');
return {
  animation: false,
  grid: { left: 14, right: 8, top: 8, bottom: 8, containLabel: true },
  tooltip: tip((k) => {
    const i = idx[k];
    return [fmt(cnt[i]) + ' patients (' + pc(100 * cnt[i] / N) + ' of ' + fmt(N) + ')']
      .concat(cnt[i] ? [soft(fmt(ctl[i]) + ' of ' + fmt(cnt[i]) + ' controlled (' + pc(100 * ctl[i] / cnt[i]) + ')')] : []);
  }, (k) => label[idx[k]], { axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(110,127,141,0.12)' } } }),
  // No value axis: every bar carries its count; the spare width keeps the end labels inside the panel.
  xAxis: { type: 'value', min: 0, max: (v) => v.max * 2, show: false },
  yAxis: { type: 'category', inverse: true, data: idx.map((i) => label[i]), axisTick: { show: false },
    axisLabel: { color: C.text, fontSize: 12 }, axisLine: { lineStyle: { color: C.axisLine } } },
  series: [{
    type: 'bar', name: 'Patients', barMaxWidth: 22, barCategoryGap: '28%',
    data: idx.map((i) => ({ value: cnt[i], itemStyle: ord[i] === 9
      ? { color: colorOf(ord[i]), borderColor: C.stepOff, borderType: 'dashed', borderWidth: 1, borderRadius: [0, 2, 2, 0] }
      : { color: colorOf(ord[i]), borderRadius: [0, 2, 2, 0] } })),
    label: { show: true, position: 'right', color: C.text, fontSize: 12, formatter: (q) => end(idx[q.dataIndex]) }
  }]
};

