// Look at these first: at most three flagged facilities, most patients first.
const root = rpt.mount('.rpt-adh-look');
if (!root) { return; }
const { esc, fmt, num } = rpt;
const share = (k, N) => (num(N) ? Math.round(1000 * (num(k) || 0) / num(N)) / 10 : null);
const offHit = (r) => num(r.off_protocol_pct) !== null && num(r.off_protocol_pct) >= num(r.off_protocol_pct_line);
const oneHit = (r) => num(r.one_medicine_pct) !== null && num(r.one_medicine_pct) >= num(r.one_medicine_pct_line);
const reasonOf = (r) => [
  offHit(r) ? fmt(r.off_n) + ' of ' + fmt(r.cohort_n) + ' patients are off protocol (' + rpt.pct(share(r.off_n, r.cohort_n)) + ').' : '',
  oneHit(r) ? fmt(r.one_n) + ' of ' + fmt(r.cohort_n) + ' patients are on one medicine (' + rpt.pct(share(r.one_n, r.cohort_n)) + ').' : ''
].filter(Boolean).join(' ');
const list = rpt.rows('A').sort((a, b) => (num(b.cohort_n) || 0) - (num(a.cohort_n) || 0)
  || String(a.org_unit_name).localeCompare(String(b.org_unit_name))).slice(0, 3);
root.innerHTML = '<h3 class="rpt-card-title">Look at these first</h3>' + (list.length
  ? '<ol class="rpt-look">' + list.map((r) => '<li><span class="rpt-look-name">' + esc(r.org_unit_name) + '</span>'
    + '<div class="rpt-look-line">' + esc(reasonOf(r)) + '</div></li>').join('') + '</ol>'
  : '<div class="rpt-muted">' + esc(rpt.NO_FLAGS) + ' Check the table below.</div>');

