// Facility table: Facility, Patients, On 2 or 3 medicines, Off protocol, BP controlled, Why look here.
const root = rpt.mount('.rpt-adh-table');
if (!root) { return; }
const { esc, fmt, num, yes } = rpt;
const share = (k, N) => (num(N) ? Math.round(1000 * (num(k) || 0) / num(N)) / 10 : null);
const offHit = (r) => num(r.off_protocol_pct) !== null && num(r.off_protocol_pct) >= num(r.off_protocol_pct_line);
const oneHit = (r) => num(r.one_medicine_pct) !== null && num(r.one_medicine_pct) >= num(r.one_medicine_pct_line);
const reasonOf = (r) => [
  offHit(r) ? fmt(r.off_n) + ' of ' + fmt(r.cohort_n) + ' patients are off protocol (' + rpt.pct(share(r.off_n, r.cohort_n)) + ').' : '',
  oneHit(r) ? fmt(r.one_n) + ' of ' + fmt(r.cohort_n) + ' patients are on one medicine (' + rpt.pct(share(r.one_n, r.cohort_n)) + ').' : ''
].filter(Boolean).join(' ');
// Percent with its count beside it, muted.
const pn = (k, r) => (num(r.cohort_n) ? rpt.pct(share(k, r.cohort_n)) + ' <span class="rpt-cnt">' + esc(fmt(k)) + '</span>' : '—');
const of = (k, r) => fmt(k) + ' of ' + fmt(r.cohort_n) + ' patients';
rptTable(root, {
  report: 'adherence',
  rows: rpt.rows('A'),
  caption: 'Patients by medicines and BP control, by facility. Flagged facilities come first.',
  columns: [
    { label: 'Patients', num: true, value: (r) => num(r.cohort_n), cell: (r) => fmt(r.cohort_n) },
    { label: 'On 2 or 3 medicines', num: true, guard: true, value: (r) => share(r.two_three_n, r.cohort_n), cell: (r) => pn(r.two_three_n, r), title: (r) => of(r.two_three_n, r) },
    { label: 'Off protocol', num: true, guard: true, value: (r) => num(r.off_protocol_pct), cell: (r) => pn(r.off_n, r), title: (r) => of(r.off_n, r) },
    { label: 'BP controlled', num: true, guard: true, value: (r) => num(r.controlled_pct),
      cell: (r) => (num(r.controlled_pct) === null ? '—' : '<span class="rpt-ctl">' + rpt.pct(r.controlled_pct) + '</span> <span class="rpt-cnt">' + esc(fmt(r.controlled_n)) + '</span>'),
      title: (r) => of(r.controlled_n, r) + ' with BP under 140/90' }
  ],
  flagNames: (r) => [offHit(r) ? 'Many off protocol' : '', oneHit(r) ? 'Mostly one medicine' : ''],
  reason: reasonOf,
  guardName: 'Too few patients',
  guardReason: (r) => rpt.needAtLeast(r.min_cohort, r.cohort_n),
  alsoOn: [],
  size: (r) => num(r.cohort_n)
});
